import { d as db } from "../../../../../../chunks/db.js";
import { g as getEmpresaId } from "../../../../../../chunks/get-empresa-id.js";
import { g as getUserId } from "../../../../../../chunks/get-user-id.js";
import { fail } from "@sveltejs/kit";
import { D as DocumentoFiscalService } from "../../../../../../chunks/documento-fiscal.service.js";
class FaturaAdiantamentoService {
  docService = new DocumentoFiscalService();
  async criarFaturaAdiantamento(dados) {
    return await db.$transaction(async (tx) => {
      const { numero, numeroSequencial } = await this.docService.gerarNumeroSequencial(
        dados.empresaId,
        "FA",
        // Fatura Adiantamento
        tx
      );
      const { itensCalculados, resumo } = this.docService.calcularTotais(dados.itens);
      const documento = await tx.documentoFiscal.create({
        data: {
          empresaId: dados.empresaId,
          clienteId: dados.clienteId,
          createdBy: dados.usuarioId,
          tipoDocumento: "FACTURA_ADIANTAMENTO",
          status: "EMITIDO",
          numero,
          serie: "FA",
          numeroSequencial,
          dataEmissao: dados.dataEmissao,
          dataVencimento: dados.dataVencimento,
          moeda: dados.moeda,
          subtotal: resumo.subtotal,
          totalDesconto: resumo.totalDesconto,
          totalImpostos: resumo.totalImpostos,
          total: resumo.total,
          observacao: dados.observacao || "Fatura de Adiantamento",
          retencao: dados.retencao || 0,
          formaPagamento: dados.formaPagamento,
          referenciaOriginal: dados.referenciaOriginal,
          regimeFiscal: dados.regimeFiscal || "NORMAL",
          hashDocumento: this.docService.gerarHashDocumento({
            numero,
            dataEmissao: dados.dataEmissao,
            total: resumo.total.toFixed(2),
            empresaId: dados.empresaId,
            tipo: "FA"
          })
        }
      });
      for (const item of itensCalculados) {
        await tx.itemDocumento.create({
          data: {
            documentoId: documento.id,
            empresaId: dados.empresaId,
            // Não vinculamos produtoId físico se for puramente financeiro,
            // mas se o usuário vincular, não geramos movimento de estoque.
            produtoId: item.produtoId,
            codigo: item.codigo,
            descricao: item.descricao,
            quantidade: item.quantidade,
            precoUnitario: item.precoUnitario,
            desconto: item.desconto || 0,
            taxa: item.taxa || 0,
            subtotal: item.subtotal,
            total: item.total,
            motivoIsencao: item.motivoIsencao
          }
        });
      }
      return documento;
    });
  }
}
const load = async ({ request }) => {
  const empresaId = await getEmpresaId(request);
  const clientes = await db.cliente.findMany({
    where: { empresaId },
    orderBy: { nome: "asc" }
  });
  const produtos = await db.produto.findMany({
    where: { empresaId },
    orderBy: { descricao: "asc" },
    include: { taxa: true }
  });
  return {
    clientes,
    produtos: produtos.map((p) => ({
      ...p,
      precoUnitario: p.precoUnitario.toNumber(),
      desconto: p.desconto.toNumber(),
      taxa: p.taxa ? { ...p.taxa, valor: p.taxa.valor.toNumber() } : null
    }))
  };
};
const actions = {
  emitir: async ({ request }) => {
    const empresaId = await getEmpresaId(request);
    const usuarioId = await getUserId(request);
    if (!usuarioId) {
      return fail(401, { error: "Usuário não autenticado" });
    }
    const data = await request.formData();
    const clienteId = data.get("clienteId")?.toString();
    const dataEmissao = data.get("dataEmissao")?.toString();
    const dataVencimento = data.get("dataVencimento")?.toString();
    const moeda = data.get("moeda")?.toString();
    const observacao = data.get("observacao")?.toString();
    const formaPagamento = data.get("formaPagamento")?.toString();
    const retencao = Number(data.get("retencao") || 0);
    const itensJSON = data.get("itens")?.toString();
    if (!clienteId || !dataEmissao || !dataVencimento || !moeda || !itensJSON || !formaPagamento) {
      return fail(400, { error: "Campos obrigatórios faltando" });
    }
    try {
      const itens = JSON.parse(itensJSON);
      const docService = new FaturaAdiantamentoService();
      const documento = await docService.criarFaturaAdiantamento({
        empresaId,
        clienteId,
        usuarioId,
        dataEmissao: new Date(dataEmissao),
        dataVencimento: new Date(dataVencimento),
        moeda,
        itens,
        observacao,
        formaPagamento,
        retencao
      });
      return {
        success: true,
        message: "Fatura de Adiantamento emitida com sucesso",
        documentoId: documento.id,
        numero: documento.numero
      };
    } catch (error) {
      console.error("Erro ao emitir adiantamento:", error);
      return fail(500, { error: error.message || "Erro ao emitir documento" });
    }
  }
};
export {
  actions,
  load
};
